import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2018-MAR-01 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-MAR-01 :: Ceph Performance Weekly","date":"2018-03-01T00:00:00.000Z","updated":"2018-03-02T00:00:00.000Z","tags":["Ceph","分布式存储","元数据管理","缓存策略","性能优化","RocksDB","BlueStore","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-MAR-01_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-MAR-01_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2018/2018-MAR-01_-_-_Ceph_Performance_Weekly.md"};function p(s,l,_,a,n,c){return i(),t("div",null,[...l[0]||(l[0]=[o("<p>在本次Ceph性能周会中，参会人员就Ceph分布式存储系统中的元数据管理、缓存策略和性能优化等问题进行了深入讨论。以下是会议的主要议题、决定的事项和后续行动计划：</p><p><strong>主要议题及讨论内容</strong>：</p><ol><li><p><strong>元数据管理</strong>：</p><ul><li>讨论了RocksDB元数据空间占用情况，发现与对象数量密切相关，尤其是对于RGW对象，元数据空间占用较大。</li><li>讨论了RocksDB和BlueStore的缓存策略，包括缓存大小、缓存优先级等。</li><li>讨论了优化缓存策略的方法，如动态调整缓存大小和利用RocksDB接口查询索引和过滤器大小以分配缓存内存。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li>讨论了RocksDB的压缩优化，包括是否在RocksDB中压缩块缓存，以及如何平衡压缩带来的CPU开销和存储空间占用。</li><li>讨论了日志优化，包括减少日志条目数量，以及是否禁用日志操作。</li><li>讨论了锁优化，包括减少锁争用，以及使用无锁数据结构。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>讨论了Ceph Star的进展情况，以及如何将Ceph Star与现有存储引擎集成。</li><li>讨论了性能回归问题，以及如何避免性能回归。</li></ul></li></ol><p><strong>决定的事项</strong>：</p><ul><li>继续使用默认的50/50缓存分配策略。</li><li>根据对象数量和键值对数量动态调整缓存大小。</li><li>利用RocksDB接口查询索引和过滤器大小以分配缓存内存。</li><li>进行压缩优化，平衡CPU开销和存储空间占用。</li><li>进行日志优化，减少日志条目数量。</li><li>进行锁优化，减少锁争用。</li><li>加快Ceph Star的进展。</li><li>避免性能回归。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>发布RocksDB元数据空间占用测试数据。</li><li>尝试根据对象数量和键值对数量动态调整缓存大小。</li><li>进行RocksDB压缩优化。</li><li>进行日志优化。</li><li>进行锁优化。</li><li>继续推进Ceph Star相关工作。</li></ul><p>本次会议通过讨论和决策，为Ceph分布式存储系统的元数据管理、缓存策略和性能优化提供了明确的解决方案和后续行动计划，有助于提高Ceph的效率和性能。</p>",8)])])}const d=e(r,[["render",p]]);export{C as __pageData,d as default};
